from modele import *

def A(i,t,e,c,m,k,fig=None):
    return E(t,e,c,m,k,figure=fig if fig is not None else f'script-{i:02}')

chapitre(17,'pensee-informatique','Pensée informatique et algorithmique','5 · Pensée informatique et raisonnement',
'Variables · Conditions composées · Boucles conditionnelles · Blocs personnalisés',
['Lire, exécuter à la main et compléter un script par blocs.','Utiliser plusieurs variables, des conditions composées et des boucles conditionnelles.','Structurer un programme avec des blocs personnalisés et simuler une expérience.'],['Calcul numérique, divisibilité et probabilités.'],[
r'''\essSection{1}{Variables, conditions et boucles}
\begin{definition}Une variable associe un nom à une valeur, que le programme peut lire et modifier. « Mettre x à 3 » remplace son contenu ; « ajouter 3 à x » augmente sa valeur actuelle. Un programme peut utiliser plusieurs variables, par exemple un compteur et une somme.\end{definition}
\begin{definition}Une condition est un test vrai ou faux, comme $x\ge10$. Une condition composée combine deux conditions : « A et B » est vraie lorsque les deux le sont ; « A ou B » est vraie lorsque l’une au moins l’est.\end{definition}
\begin{definition}La boucle « répéter $n$ fois » exécute son contenu un nombre fixé de fois. La boucle conditionnelle « répéter jusqu’à » recommence tant que sa condition est fausse et s’arrête dès qu’elle devient vraie ; elle ne termine que si le contenu fait évoluer les variables vers cette condition.\end{definition}
\begin{savoirfaire}[Exécuter à la main]Préparer un tableau avec une colonne par variable et une ligne par étape ou par tour. Exécuter dans l’ordre, en utilisant les valeurs déjà modifiées. Tester les valeurs frontières d’une condition.\end{savoirfaire}
\begin{attention}Un test n’est pas une affectation : « x = 6 » dans une condition compare, il ne modifie pas x. Les lignes indentées appartiennent au bloc qui les contient ; une ligne « fin » le ferme.\end{attention}''',
r'''\essSection{2}{Structurer et simuler}
\begin{definition}Un bloc personnalisé regroupe des instructions sous un nom ; ses paramètres lui fournissent des valeurs. Le bloc polygone(n, c) peut répéter $n$ fois « avancer de c ; tourner de $360/n$ degrés ». On l’appelle ensuite comme une seule instruction.\end{definition}
\begin{savoirfaire}[Décomposer un problème]Isoler une tâche répétée dans un bloc personnalisé, la tester seule, puis écrire le programme principal qui l’appelle. Un programme bien structuré est plus court, plus lisible et plus facile à corriger.\end{savoirfaire}
\begin{savoirfaire}[Simuler]Choisir un entier aléatoire de 1 à 6 modélise un dé équilibré. Pour deux dés indépendants, tirer deux nombres séparément. Initialiser le compteur à zéro avant la boucle, l’augmenter quand l’évènement est réalisé, puis diviser par le nombre d’essais.\end{savoirfaire}
\begin{exemple}Pour obtenir le quotient et le reste de 23 par 5, on retire 5 tant que c’est possible : $23\to18\to13\to8\to3$. Quatre soustractions ont été faites : quotient 4, reste 3. Une boucle conditionnelle automatise ce procédé.\end{exemple}
\begin{attention}Les blocs du livre représentent les instructions d’un langage de type Scratch, sans prétendre reproduire son interface. Les multiplications sont explicites.\end{attention}'''],[
A(1,'Suivre trois opérations',r"Exécuter le script et donner la valeur affichée.",r"x prend successivement 3, 8 et 16. Le bloc dire affiche $\res{16}$. Ajouter puis multiplier ne donne pas le même résultat que multiplier puis ajouter.","Écrire chaque valeur dans l’ordre.","assert (3+5)*2==16"),
A(2,'Un nombre demandé',r"Le script lit un nombre x. Donner le résultat pour 2 et pour $-4$, puis l’expression obtenue à partir de x.",r"Après ajout, on a $x+4$ ; après multiplication, $3(x+4)$. Les résultats sont $\res{18}$ et $\res0$. Les parenthèses traduisent l’ordre des blocs.","Traduire les modifications successives.","assert 3*(2+4)==18 and 3*(-4+4)==0"),
A(3,'Une boucle bornée',r"Quelle valeur affiche le script ? Combien de fois le bloc ajouter est-il exécuté ?",r"Le bloc ajouter s’exécute quatre fois. Les valeurs sont 3, 6, 9, 12. La sortie est $\res{12}$. Le bloc dire placé après la boucle s’exécute une seule fois.","Repérer les limites de la boucle.","assert sum([3]*4)==12"),
A(4,'Un test et deux branches',r"Exécuter le script pour les entrées 9, 10 et 14.",r"Le test est $x\ge10$, donc il est faux pour 9 et vrai pour 10 et 14. Les sorties sont respectivement $\res{\text{petit, grand, grand}}$. La borne 10 conduit bien à la branche du test vrai.","Tester la valeur située à la frontière.","assert [a>=10 for a in [9,10,14]]==[False,True,True]"),
A(5,'Doubler plusieurs fois',r"Quelle est la valeur finale de x ? Un élève propose $2+3\times2$. Expliquer son erreur.",r"Les trois tours donnent 4, 8, 16. La sortie est $\res{16=2\times2^3}$. Le script multiplie à chaque tour ; il n’ajoute pas 2 trois fois.","Distinguer additions et multiplications répétées.","assert 2*2**3==16 and 2+3*2!=16"),
A(6,'Deux variables',r"Suivre les variables s et n à chaque tour, puis donner le résultat. Que calcule ce script ?",r"Au départ $(s;n)=(0;1)$. Après les cinq tours : $(1;2),(3;3),(6;4),(10;5),(15;6)$. La sortie est $\res{15}$ : le script calcule la somme $1+2+3+4+5$. L’ajout à s précède l’augmentation de n.","Faire un tableau des deux variables.","assert sum(range(1,6))==15"),
A(7,'Répéter jusqu’à',r"Donner les valeurs successives de x et le nombre de tours.",r"En partant de 0, on obtient 6, 12, 18 puis 24. Le test $x\ge20$ devient vrai à 24 : $\res{4\text{ tours}}$ et sortie $\res{24}$. La boucle ne s’arrête pas à 20, qui n’est jamais atteint.","Vérifier le test avant chaque nouveau tour.","assert [6*i for i in range(5)]==[0,6,12,18,24]"),
A(8,'Une condition composée',r"Le script teste si un nombre appartient à une plage. Donner l’affichage pour 9, 10, 20 et 21. Que se passerait-il si l’on remplaçait « et » par « ou » ?",r"La condition est vraie seulement si $x\ge10$ et $x\le20$ sont vraies toutes les deux. Les affichages sont $\res{\text{hors, dans, dans, hors de la plage}}$ ; les bornes 10 et 20 sont incluses. Avec « ou », tout nombre vérifierait l’une des deux conditions : le script afficherait toujours « dans la plage ».","Évaluer chaque condition simple, puis les combiner.","assert [(a>=10 and a<=20) for a in [9,10,20,21]]==[False,True,True,False] and all((a>=10 or a<=20) for a in range(-50,50))"),
A(9,'Énumérer des diviseurs',r"Quelles valeurs sont affichées ? Pourquoi commence-t-on d à 1 et non à 0 ?",r"Le script teste d de 1 à 12 et affiche $\res{1,2,3,4,6,12}$. Ce sont tous les diviseurs positifs de 12. Commencer par 0 rendrait le calcul du reste impossible, car on ne divise pas par zéro.","Comprendre l’intervalle parcouru par la boucle.","assert [d for d in range(1,13) if 12%d==0]==[1,2,3,4,6,12]"),
A(10,'Le reste par soustractions',r"Le script demande deux entiers positifs a et b. Exécuter le script pour $a=23$ et $b=5$, puis pour $a=3$ et $b=5$. Que calculent les variables q et r ?",r"Pour 23 et 5, r prend les valeurs 23, 18, 13, 8, 3 et q compte 4 soustractions : affichage $\res{4\text{ puis }3}$. Pour 3 et 5, le test $r<b$ est vrai dès le départ : affichage $\res{0\text{ puis }3}$. Le script calcule le quotient q et le reste r de la division euclidienne de a par b : $23=5\times4+3$.","Suivre r et q à chaque tour, en testant la condition avant le tour.","assert divmod(23,5)==(4,3) and divmod(3,5)==(0,3)"),
A(11,'Une boucle qui dépasse',r"Combien de tours effectue le script ? Remplacer « multiplier par 2 » par « ajouter 0 » permettrait-il encore de terminer ?",r"Les valeurs sont 1, 2, 4, 8, 16, 32, 64. Il faut $\res6$ tours avant $x>50$. Avec « ajouter 0 », x reste 1 ; le test ne devient jamais vrai et la boucle ne termine pas.","Prouver que la variable progresse vers la condition d’arrêt.","assert 2**5<=50<2**6"),
A(12,'Un bloc personnalisé',r"Le bloc carré(c) trace un carré et revient au même point avec la même orientation. Expliquer ce que dessine le programme principal. Quelle longueur est tracée au total ?",r"Le programme trace trois carrés de côté 30, en relevant le stylo pour avancer de 40 entre deux carrés : leurs points de départ sont espacés de 40 unités. La longueur tracée vaut $3\times4\times30=\res{360}$ unités. Le déplacement n’est pas dans le bloc carré, sinon il déplacerait aussi les coins.","Séparer le motif répété et le déplacement entre motifs.","assert 3*4*30==360 and [40*i for i in range(3)]==[0,40,80]",fig='script-carres'),
A(13,'Simuler un dé',r"Compléter le script pour compter les six sur 600 lancers d’un dé. Où placer l’initialisation et le calcul de fréquence ? Quelle valeur la fréquence affichée devrait-elle approcher ?",r"On met succès à $\res0$ avant la boucle ; on ajoute $\res1$ à succès quand le dé vaut 6 ; on affiche succès/$\res{600}$ après la boucle. La fréquence devrait approcher la probabilité $1/6\approx0{,}17$, sans être forcément égale.","Initialiser une fois, compter à chaque tour, diviser à la fin.","assert Rational(100,600)==Rational(1,6)",fig='script-simulation'),
A(14,'Deux dés et un « ou »',r"Le script simule 1000 lancers de deux dés. Quel évènement compte-t-il ? Calculer sa probabilité. Parmi les affichages 0,17 ; 0,31 et 0,50, lequel est plausible ?",r"Il compte les lancers où le premier dé ou le second donne 6 : l’évènement « au moins un six ». Sa probabilité vaut $1/6+1/6-1/36=\res{11/36}\approx0{,}31$. L’affichage plausible est $\res{0{,}31}$ ; 0,17 correspondrait à un seul dé et 0,50 serait très éloigné pour 1000 lancers.","Traduire la condition composée en évènement, puis utiliser la relation de la réunion.","assert Rational(1,6)*2-Rational(1,36)==Rational(11,36) and round(11/36,2)==0.31",fig='script-deux-des'),
A(15,'Des polygones réguliers',r"Le bloc polygone(n, c) trace un polygone régulier à $n$ côtés de longueur c. Le programme principal l’appelle avec n allant de 3 à 6. Nommer les figures tracées, donner l’angle de rotation pour l’hexagone et la longueur totale tracée.",r"On obtient un $\res{\text{triangle équilatéral, un carré, un pentagone et un hexagone réguliers}}$. Pour l’hexagone, le lutin tourne de $360/6=\res{60^\circ}$ à chaque sommet. La longueur totale vaut $30\times(3+4+5+6)=\res{540}$ unités. Après chaque polygone, le lutin a tourné de 360° et revient à son point de départ.","Exécuter le bloc pour chaque valeur du paramètre.","assert 30*(3+4+5+6)==540 and 360/6==60",fig='script-polygones')
],reperes=['Variables et exécution à la main','Conditions simples et composées','Boucles bornées et conditionnelles','Blocs personnalisés et simulations'],deco='algorithmique')

chapitre(18,'raisonner','Raisonner et préparer le brevet','5 · Pensée informatique et raisonnement',
'Conjecturer · Démontrer · Réfuter · Rédiger · Vérifier',
['Distinguer exemple, conjecture, preuve et contre-exemple.','Utiliser réciproque, contraposée et raisonnement par l’absurde.','Organiser le temps et la rédaction de l’épreuve du brevet.'],['Ensemble des chapitres précédents.'],[
r'''\essSection{1}{Les formes du raisonnement}
\begin{definition}Une conjecture est une affirmation que l’on pense vraie après des observations. Une preuve établit une conclusion à partir d’hypothèses, de définitions et de propriétés. Un seul contre-exemple suffit à réfuter une affirmation générale ; plusieurs exemples ne suffisent pas à la démontrer.\end{definition}
\begin{definition}Pour une propriété « si $P$, alors $Q$ », la réciproque est « si $Q$, alors $P$ » et la contraposée « si $Q$ est faux, alors $P$ est faux ». La contraposée d’une propriété vraie est vraie ; sa réciproque peut être fausse.\end{definition}
\begin{savoirfaire}[Raisonner par l’absurde]Supposer le contraire de ce que l’on veut prouver, en déduire une contradiction, puis conclure que la supposition était fausse. Exemple : un triangle ne peut pas avoir deux angles droits, sinon la somme de ses angles dépasserait $180^\circ$.\end{savoirfaire}
\begin{savoirfaire}[Démontrer]Pour une propriété des entiers, traduire « pair » par $2n$, « impair » par $2n+1$, « multiple de $d$ » par $dn$. En géométrie, distinguer une définition, une propriété et une propriété caractéristique, puis citer les hypothèses avant le théorème.\end{savoirfaire}
\begin{attention}Une mesure sur le dessin, une image de calculatrice ou un essai de programme donne une observation ; cela ne justifie pas à soi seul une propriété pour tous les cas.\end{attention}''',
r'''\essSection{2}{Une copie claire dans le temps imparti}
\begin{savoirfaire}[L’épreuve retenue]D’après la définition en vigueur à compter de la session 2027, retenue pour 2029, l’épreuve dure 2 h. Partie 1 : 20 min, sans calculatrice, 6 points d’automatismes et d’applications directes, à réponses courtes. Partie 2 : 1 h 40, calculatrice autorisée, 14 points de raisonnement et de résolution de problèmes. La première copie est relevée après 20 minutes.\end{savoirfaire}
\begin{propriete}La seconde partie ne comporte pas de QCM. Toutes les réponses doivent être justifiées, sauf indication contraire. La maîtrise de la langue est évaluée sur 2 points ; les essais et démarches engagés, même non aboutis, sont pris en compte.\end{propriete}
\begin{savoirfaire}[Rédiger]Écrire le calcul ou la propriété utile, donner les étapes essentielles, indiquer unités et arrondis, puis répondre par une phrase correctement construite. Si un résultat intermédiaire manque, poursuivre avec une valeur annoncée ou une démarche explicitée.\end{savoirfaire}
\begin{savoirfaire}[Vérifier]Relire les nombres copiés, le signe, la précision, les unités, les domaines et les ordres de grandeur. Une probabilité ne dépasse pas 1 ; une aire reste positive ; un achat entier se majore pour couvrir un besoin.\end{savoirfaire}'''],[
E('Un contre-exemple',r"« Le carré d’un nombre est toujours plus grand que ce nombre. » Réfuter cette phrase.",r"Avec $x=1/2$, $x^2=1/4<1/2$. Ce $\res{\text{seul contre-exemple suffit}}$. Avec 0 ou 1, l’inégalité stricte serait également fausse, par égalité.","Chercher un cas qui contredit exactement l’affirmation.","assert Rational(1,2)**2<Rational(1,2)"),
E('Deux entiers impairs',r"Démontrer que la somme de deux entiers impairs est paire.",r"Écrivons les deux impairs $2a+1$ et $2b+1$, avec a, b entiers. Leur somme vaut $2(a+b+1)$, donc c’est $\res{\text{un multiple de 2}}$. La preuve vaut pour tous les entiers concernés.","Traduire l’hypothèse par une écriture générale.","a,b=symbols('a b',integer=True); assert expand((2*a+1)+(2*b+1)-2*(a+b+1))==0"),
E('Réciproque et contraposée',r"On considère la propriété vraie : « Si un entier est multiple de 6, alors il est pair. » Énoncer sa réciproque et sa contraposée. Lesquelles sont vraies ?",r"Réciproque : « si un entier est pair, alors il est multiple de 6 » ; elle est $\res{\text{fausse}}$ : 4 est pair mais n’est pas multiple de 6. Contraposée : « si un entier n’est pas pair, alors il n’est pas multiple de 6 » ; elle est $\res{\text{vraie}}$, comme toute contraposée d’une propriété vraie.","Échanger hypothèse et conclusion, puis les nier.","assert 4%2==0 and 4%6!=0 and all(n%2==0 for n in range(-60,61) if n%6==0)"),
E('Un arrondi utile',r"Il faut 7,2 L d’un produit vendu en bidons de 3 L. Combien de bidons au minimum ?",r"$7{,}2/3=2{,}4$. Deux bidons n’apportent que 6 L ; trois apportent 9 L. Il faut $\res3$ bidons. L’arrondi à l’entier le plus proche ne couvre pas forcément le besoin.","Interpréter la quantité entière dans le contexte.","assert ceil(Rational('7.2')/3)==3"),
E('Une hypothèse manquante',r"Un triangle est dessiné avec deux côtés de 3 cm et 4 cm. Peut-on affirmer que le troisième vaut 5 cm ?",r"$\res{\text{Non}}$ : il faudrait savoir que les côtés de 3 et 4 cm sont perpendiculaires pour appliquer Pythagore ainsi. Un triangle de côtés 3, 4 et 6 cm existe aussi, car $3+4>6$, et son troisième côté n’est pas 5.","Identifier l’hypothèse nécessaire.","assert 3+4>6 and 3**2+4**2!=6**2"),
E('Un programme constant',r"Choisir x, ajouter 5, doubler, puis retirer deux fois le nombre de départ. Montrer que le résultat est toujours le même.",r"Le résultat est $2(x+5)-2x=2x+10-2x=\res{10}$. Des essais suggèrent ce résultat ; la simplification le prouve pour tout x.","Passer des essais à l’expression générale.","assert expand(2*(x+5)-2*x)==10"),
E('Un raisonnement par l’absurde',r"Démontrer par l’absurde qu’un triangle rectangle ne peut pas avoir un angle obtus.",r"Supposons qu’un triangle rectangle ait aussi un angle obtus, donc supérieur à $90^\circ$. La somme de ces deux angles dépasserait déjà $180^\circ$, alors que la somme des trois angles d’un triangle vaut $180^\circ$ : contradiction. La supposition est fausse : $\res{\text{aucun triangle rectangle n’a d’angle obtus}}$.","Supposer le contraire et chercher une contradiction.","assert 90+91>180"),
E('Une conjecture de divisibilité',r"On observe que $n(n+1)$ est pair pour plusieurs entiers n. Le démontrer.",r"Deux entiers consécutifs comprennent toujours un pair : si n est pair, le produit contient ce facteur ; sinon $n+1$ est pair. Dans les deux cas, $\res{n(n+1)\text{ est multiple de 2}}$. On a distingué tous les cas possibles.","Distinguer les deux parités possibles.","assert all((n*(n+1))%2==0 for n in range(-100,101))"),
E('Vérifier une équation',r"Un élève affirme que $x=4$ résout $3(x-2)=x+4$. Vérifier, puis résoudre.",r"Pour 4, les membres valent 6 et 8 : ce n’est pas une solution. $3x-6=x+4$ équivaut à $2x=10$, donc $\res{x=5}$. Le contrôle donne 9 de chaque côté.","Une substitution rapide détecte une erreur.","assert solve(3*(x-2)-(x+4),x)==[5]"),
E('Une moyenne mal interprétée',r"Une classe a une moyenne de 12/20. Est-il certain qu’au moins la moitié des notes sont supérieures ou égales à 12 ?",r"$\res{\text{Non}}$. Considérons quatre notes $10\,;10\,;10\,;18$ : leur moyenne vaut 12, mais une seule est au moins 12. La propriété de partage en deux moitiés concerne la médiane, pas la moyenne.","Construire un contre-exemple satisfaisant la donnée.","assert sum([10,10,10,18])/4==12 and sum(v>=12 for v in [10,10,10,18])<2"),
E('Une commande au meilleur prix',r"Pour 24 carnets : A vend à 2,80 € l’unité avec 6 € de livraison ; B vend des lots de 8 à 21 €, livraison gratuite. Comparer les coûts.",r"A coûte $24\times2{,}80+6=\res{73{,}20\text{ €}}$. Il faut trois lots chez B : $\res{63\text{ €}}$. B économise $\res{10{,}20\text{ €}}$. On compare les coûts totaux pour la même quantité.","Inclure conditionnement et frais fixes.","assert 24*Rational('2.8')+6==Rational('73.2') and 3*21==63"),
E('Un modèle de bassin',r"Un bassin pavé de 4 m sur 2,5 m contient 6000 L. La hauteur d’eau maximale est 0,8 m. Calculer la hauteur actuelle puis la quantité encore possible.",r"6000 L valent 6 m$^3$. La base vaut 10 m$^2$, donc la hauteur est $6/10=\res{0{,}6\text{ m}}$. Le volume maximal vaut 8 m$^3$ ; il reste $\res{2000\text{ L}}$.","Relier volume, aire de base et hauteur.","assert 4*Rational('2.5')==10 and Rational(6,10)==Rational('.6') and (8-6)*1000==2000",figure='synthese-bassin'),
E('Un hasard et un budget',r"Une tombola propose 200 billets à 3 €. Vingt billets gagnent chacun un lot coûtant 15 € à l’organisateur. Tous les billets sont vendus et chaque billet a la même chance. Calculer la probabilité qu’un billet donné gagne et le solde de l’organisation, sans autres frais.",r"La probabilité de gain vaut $20/200=\res{1/10}$. Les recettes sont 600 € et les lots coûtent 300 €. Le solde vaut $\res{300\text{ €}}$. Le résultat financier global ne décrit pas la chance d’un billet particulier.","Séparer modèle aléatoire et bilan comptable.","assert Rational(20,200)==Rational(1,10) and 200*3-20*15==300"),
E('Un maximum expliqué',r"Un rectangle a un périmètre de 40 cm. Montrer que son aire vaut $100-(x-10)^2$ si un côté vaut x, puis déterminer la plus grande aire.",r"L’autre côté vaut $20-x$, avec $0<x<20$. L’aire vaut $20x-x^2$, et $100-(x-10)^2=100-x^2+20x-100=20x-x^2$. Un carré étant positif ou nul, l’aire est au plus $\res{100\text{ cm}^2}$, valeur atteinte pour $x=10$, donc pour un carré.","Transformer l’expression avec une identité remarquable.","assert expand(100-(x-10)**2-x*(20-x))==0",figure='rectangle-fonction'),
E('Un plan de révision',r"Une élève réussit 8 automatismes sur 12, puis obtient 9/14 aux problèmes, rédaction comprise. Selon le barème des brevets blancs du livre, quelle note obtient-elle ? Quel travail cibler si ses quatre erreurs concernent les fractions ?",r"Les automatismes rapportent $8\times0{,}5=4$ points. Le total vaut $\res{13/20}$. Reprendre le cours de fractions, refaire les questions ratées sans regarder la solution, puis contrôler sur des exercices nouveaux cible la difficulté identifiée. Ce bilan guide la suite sans résumer toutes les compétences à une note.","Relier le bilan à une action précise.","assert 8*Rational(1,2)+9==13")
],reperes=['Conjecture, preuve et contre-exemple','Réciproque, contraposée et absurde','Problèmes de synthèse','Méthode et format du brevet 2029'],deco='algorithmique')
